# update_account_drawer_ui.ps1
# Replaces lib\shared\widgets\account_drawer.dart with a version matching
# the reference Account screen UI (avatar+verified name, Total Value card
# with return badge, "Unlock Pro Trading Tools" promo, highlighted
# "Account Overview" row, Account Details / Statements & Tax / Settings,
# then More section and Log Out). Refer & Earn is intentionally NOT included.
#
# Run from the stockpro-frontend repo root (the folder that contains 'lib').
# Usage:  powershell -ExecutionPolicy Bypass -File update_account_drawer_ui.ps1

$ErrorActionPreference = "Stop"

$targetRelPath = "lib\shared\widgets\account_drawer.dart"
$targetPath = Join-Path (Get-Location) $targetRelPath

if (-not (Test-Path (Split-Path $targetPath -Parent))) {
    Write-Host "ERROR: Can't find $targetRelPath from here." -ForegroundColor Red
    Write-Host "Run this script from the stockpro-frontend repo root (the folder that contains 'lib')." -ForegroundColor Yellow
    exit 1
}

$base64Content = ""

$bytes = [Convert]::FromBase64String($base64Content)
$utf8NoBom = New-Object System.Text.UTF8Encoding($false)
[System.IO.File]::WriteAllText($targetPath, $utf8NoBom.GetString($bytes), $utf8NoBom)

Write-Host "Updated: $targetRelPath" -ForegroundColor Green
Write-Host "Drawer now matches the reference Account UI (avatar+verified badge, Total Value card with % badge, Unlock Pro Trading Tools promo, highlighted Account Overview row). Refer & Earn was NOT added." -ForegroundColor Cyan
Write-Host "Next: flutter run" -ForegroundColor Cyan
